//该代码存在一定问题
//他的方程形式已定
//第一个文件的代码更好
#include <stdio.h>
#include <ctype.h>
// 处理符号字符（+、-、=）
void handleSymbol(char c, int *f, int *now, int *k, int *b, int *x, int *r) {
    if (c == '-') {
        *b += (*now) * (*f) * (*x);
        *x = 0;
        *f = -1;
        *r = 0;
    } else if (c == '+') {
        *b += (*now) * (*f) * (*x);
        *x = 0;
        *f = 1;
        *r = 0;
    } else if (c == '=') {
        *b += (*now) * (*f) * (*x);
        *x = 0;
        *f = 1;
        *now = -1;
        *r = 0;
    }
}
// 处理未知数字符
void handleVariable(char c, int *f, int *now, int *k, int *x, int *r, char *a) {
    if (*r) {
        *k += (*now) * (*f) * (*x);
        *x = 0;
    } else {
        *k += (*now) * (*f);
    }
    *a = c;
    *r = 0;
}
// 处理数字字符
void handleDigit(char c, int *x, int *r) {
    *x = *x * 10 + (c - '0');
    *r = 1;
}
int main() {
    char c, a;  // c 用来读入, a 是未知数名
    int f = 1;  // f 初始化为正，表示当前项的符号，1 为正，-1 为负
    int now = 1; // now 初始为左，表示当前处于方程的左边，1 表示左边，-1 表示右边
    int k = 0, b = 0, x = 0; // k 表示未知数的系数，b 表示常数项，x 用于临时存储当前读取的数字
    int r = 0; // 用来判是否有数字读入，0 表示没有，1 表示有
    // 读取输入字符
    while ((c = getchar()) != EOF) {
        if (c == '-' || c == '+' || c == '=') {
            handleSymbol(c, &f, &now, &k, &b, &x, &r);
        } else if (isalpha(c)) {
            handleVariable(c, &f, &now, &k, &x, &r, &a);
        } else if (isdigit(c)) {
            handleDigit(c, &x, &r);
        }
    }
    // 加上最后一项常数（若最后一项是未知数则会加 0）
    b += now * f * x;
    // 计算方程的解
    double ans = (double)(-b) / k;
    // 特判，将 -0.0 改为 0
    if (ans == -0.0) {
        ans = 0;
    }
    // 保留三位小数输出
    printf("%c=%.3lf", a, ans);

    return 0;
}
/*# [NOIP 2000 普及组] 计算器的改良
## 题目背景
NCL 是一家专门从事计算器改良与升级的实验室，最近该实验室收到了某公司所委托的一个任务：
需要在该公司某型号的计算器上加上解一元一次方程的功能。实验室将这个任务交给了一个刚进入的新手 ZL 先生。
## 题目描述
为了很好的完成这个任务，ZL 先生首先研究了一些一元一次方程的实例：
- $4+3x=8$。
- $6a-5+1=2-2a$。
- $-5+12y=0$。
ZL 先生被主管告之，在计算器上键入的一个一元一次方程中，只包含整数、小写字母及 `+`、`-`、`=` 
这三个数学符号（当然，符号“`-`”既可作减号，也可作负号）。方程中并没有括号，也没有除号，方程中的字母表示未知数。
你可假设对键入的方程的正确性的判断是由另一个程序员在做，或者说可认为键入的一元一次方程均为合法的，且有唯一实数解。
## 输入格式
一个一元一次方程。
## 输出格式
解方程的结果（精确至小数点后三位）。
## 样例 #1
### 样例输入 #1
```
6a-5+1=2-2a
```
### 样例输出 #1
```
a=0.750
```*/